// '1'인 칸끼리 상하좌우로 이어진 덩어리(섬)의 수와 크기
int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
int fill(int x, int y) {                 // (x, y)가 속한 섬을 칠하고 크기를 돌려준다
    seen[x][y] = true;
    int size = 1;
    for (int d = 0; d < 4; d++) {
        int a = x + dx[d], b = y + dy[d];
        if (0 <= a && a < R && 0 <= b && b < C && g[a][b] == '1' && !seen[a][b])
            size += fill(a, b);
    }
    return size;
}
